import{_ as a,o as n,c as e,a2 as i}from"./chunks/framework.CjPXnAcb.js";const g=JSON.parse('{"title":"Node.js 与 npm：给 JavaScript 搭个舞台","description":"","frontmatter":{"title":"Node.js 与 npm：给 JavaScript 搭个舞台"},"headers":[],"relativePath":"prereq/02-node-and-npm.md","filePath":"prereq/02-node-and-npm.md"}'),t={name:"prereq/02-node-and-npm.md"};function o(r,s,p,l,d,h){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="_02-·-node-js-与-npm-给-javascript-搭个舞台" tabindex="-1">02 · Node.js 与 npm：给 JavaScript 搭个舞台 <a class="header-anchor" href="#_02-·-node-js-与-npm-给-javascript-搭个舞台" aria-label="Permalink to &quot;02 · Node.js 与 npm：给 JavaScript 搭个舞台&quot;">​</a></h1><blockquote><p>一句话说清这课解决什么问题：搞明白为什么搭个 Wiki 还得装 Node.js，以及 npm 这个「应用商店」怎么帮你把 VitePress 请到电脑上。</p></blockquote><h2 id="它是什么-大白话-一个生活比喻" tabindex="-1">它是什么？（大白话 + 一个生活比喻） <a class="header-anchor" href="#它是什么-大白话-一个生活比喻" aria-label="Permalink to &quot;它是什么？（大白话 + 一个生活比喻）&quot;">​</a></h2><p>JavaScript（简称 JS）这门语言，原本只能在浏览器里跑——它是给网页写的伴舞，离开浏览器就没了舞台。可以想象成<strong>剧场驻演</strong>的演员：只在这家剧场（浏览器）演出，哪里都去不了。</p><p><strong>Node.js</strong> 就是给 JS 搭的<strong>巡演舞台</strong>：装上它，JS 就能脱离浏览器，直接在你的电脑上独立运行。于是 JS 能干的事一下子多了——写后端、写脚本、跑建站工具，都行。</p><p><strong>npm</strong> 是 JS 世界的<strong>应用商店 + 快递员</strong>（npm = Node Package Manager）。全世界的 JS 开发者把写好的工具包放到 npm 的中央仓库，你敲一条命令，npm 就帮你下载到本地。<strong>依赖</strong>这个词以后会常常见到，意思就是「别人写好的现成轮子」——你不必重新发明轮子，直接拿来用。</p><p>还有一个词：<strong>package.json</strong>——项目根目录下的一个文件，它是这个项目的<strong>采购清单</strong>：写明了项目叫什么、需要哪些依赖、各是什么版本。npm 看着它就知道该去进什么货。</p><h2 id="为什么我们需要它-和你要做的-wiki-挂钩" tabindex="-1">为什么我们需要它？（和你要做的 Wiki 挂钩） <a class="header-anchor" href="#为什么我们需要它-和你要做的-wiki-挂钩" aria-label="Permalink to &quot;为什么我们需要它？（和你要做的 Wiki 挂钩）&quot;">​</a></h2><p>你可能会问：我以后要学 Python 做大模型应用，为什么现在要装 JS 的东西？</p><p>因为你的 Wiki 站点要用 <strong>VitePress</strong> 搭，而 VitePress 本身就是一个用 JS 写成的程序。它自己不会跑，得有舞台——这个舞台就是 Node.js。装好 Node.js 的同时，npm 也就附带装上了，你才能敲 <code>npm install</code> 把 VitePress 请到电脑上。</p><p>链条就是这样：<strong>Node.js（舞台）→ npm（快递员）→ VitePress（建站工具）→ 你的 Wiki</strong>。</p><h2 id="动手试一试-核心命令" tabindex="-1">动手试一试（核心命令） <a class="header-anchor" href="#动手试一试-核心命令" aria-label="Permalink to &quot;动手试一试（核心命令）&quot;">​</a></h2><p>先确认 Node.js 已装好（没装的话去 nodejs.org 下载 LTS 版安装即可）。打开 cmd，逐条试：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">node --version</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 查询 Node.js 的版本号（比如输出 v22.11.0），有版本号 = 装好了</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">node -e </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;console.log(1+1)&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 让 Node 直接执行一小段 JS 代码（-e = evaluate）；</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> console.log 是 JS 的「打印出来」，屏幕上会输出 2</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">npm --version</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 查询 npm 的版本号，确认快递员也上岗了</span></span></code></pre></div><p>以后在你的 Wiki 项目里，最常用的一条是：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">npm install --registry=https://registry.npmmirror.com/</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 按采购清单（package.json）下载所有依赖</span></span></code></pre></div><p>这条命令在干什么？拆成三步看，npm install 本质上就是：</p><ol><li><strong>读清单</strong>：打开项目里的 package.json，看看要买哪些东西。</li><li><strong>去仓库下载</strong>：到 npm 的中央仓库把这些包一个个拉下来。</li><li><strong>放进仓库间</strong>：全部塞进项目下的 <strong>node_modules</strong> 文件夹——这个文件夹就是「轮子仓库」，几十上百个依赖都住在里面，不用手改，也别手动动它。</li></ol><p>末尾的 <code>--registry=...</code> 是说「换一家分仓取货」：npm 的主仓库在国外，国内访问慢。<strong>镜像</strong>就是主仓在国内开的<strong>分仓</strong>，货完全一样但离你近。国内最常用的是 npmmirror，加上这个参数，下载速度常常快十倍。</p><h2 id="常见报错与怎么读它" tabindex="-1">常见报错与怎么读它 <a class="header-anchor" href="#常见报错与怎么读它" aria-label="Permalink to &quot;常见报错与怎么读它&quot;">​</a></h2><p>真实案例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&#39;node&#39; 不是内部或外部命令，也不是可运行的程序或批处理文件。</span></span></code></pre></div><p>上一课刚讲过：<strong>环境变量</strong>里的 <strong>PATH</strong> 是系统的地址簿，敲一个命令名，系统就按地址簿挨个文件夹找程序。这条报错的意思是：翻遍地址簿也没找到 node.exe。</p><p>两种可能，从报错本身推不出来，要自己排查：</p><ol><li><strong>根本没装 Node.js</strong>——解决：去 nodejs.org 下载 LTS 版安装，装完<strong>关掉 cmd 重开</strong>（PATH 的改动老窗口看不到）。</li><li><strong>装了，但没进地址簿</strong>——常见于便携版（解压即用的绿色版，没人替你登记户口）。解决：把 node.exe 所在文件夹手动加进 PATH；或者像你的便携版 git 一样，每次敲完整路径。</li></ol><p>判断到底是哪种最快的办法：打开安装位置看一眼，node.exe 在不在。在，就是 PATH 问题；不在，就是没装。</p><h2 id="自测两题" tabindex="-1">自测两题 <a class="header-anchor" href="#自测两题" aria-label="Permalink to &quot;自测两题&quot;">​</a></h2><details class="details custom-block"><summary>第 1 题：你以后主要写 Python，为什么搭 Wiki 还要先装 Node.js？</summary></details><details class="details custom-block"><summary>看答案</summary><p>因为建站工具 VitePress 是用 JavaScript 写的，它需要在 Node.js 这个「舞台」上才能运行；而下载安装 VitePress 用的 npm，也是随 Node.js 一起装上的。Python 是你以后写大模型应用用的，两者不冲突。</p></details><details class="details custom-block"><summary>第 2 题：<code>npm install</code> 慢得像蜗牛，加什么参数能提速？为什么有效？</summary></details><details class="details custom-block"><summary>看答案</summary><p>加 <code>--registry=https://registry.npmmirror.com/</code>。npm 主仓库在国外，直连很慢；这个参数让 npm 从国内的<strong>镜像</strong>（npmmirror 分仓）取货——分仓的货和主仓一致，但物理上离你近，所以快得多。</p></details><h2 id="下一课" tabindex="-1">下一课 <a class="header-anchor" href="#下一课" aria-label="Permalink to &quot;下一课&quot;">​</a></h2><p><a href="./03-git-and-github.html">03 · Git 与 GitHub</a>——学会用「时光机」管理代码，把你的 Wiki 发布到网上。</p>`,33)])])}const m=a(t,[["render",o]]);export{g as __pageData,m as default};
